#requires -RunAsAdministrator
#requires -Version 5.1
[CmdletBinding()]param()
$root='C:\ProgramData\BlueRidge\RemoteAccessReports';$logs='C:\ProgramData\BlueRidge\Logs';New-Item -ItemType Directory -Force -Path $root,$logs|Out-Null;$s=Get-Date -Format yyyyMMdd-HHmmss;$d=Join-Path $root "remote-$env:COMPUTERNAME-$s";New-Item -ItemType Directory -Force -Path $d|Out-Null;Start-Transcript -Path (Join-Path $logs 'rdp-openssh-diagnostics.log') -Append|Out-Null
try{Get-Service TermService,SessionEnv,UmRdpService,sshd,ssh-agent -ErrorAction SilentlyContinue|Select Name,Status,StartType|Export-Csv (Join-Path $d services.csv) -NoTypeInformation;Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue|Where LocalPort -in 22,3389,5985,5986|Export-Csv (Join-Path $d listeners.csv) -NoTypeInformation;Get-NetFirewallRule -ErrorAction SilentlyContinue|Where DisplayGroup -match 'Remote Desktop|OpenSSH|Windows Remote Management'|Select DisplayName,DisplayGroup,Enabled,Direction,Action,Profile|Export-Csv (Join-Path $d firewall.csv) -NoTypeInformation;Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -ErrorAction SilentlyContinue|Select fDenyTSConnections|Export-Csv (Join-Path $d rdp-registry.csv) -NoTypeInformation;Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -ErrorAction SilentlyContinue|Select UserAuthentication,SecurityLayer,PortNumber|Export-Csv (Join-Path $d rdp-security.csv) -NoTypeInformation;if(Test-Path 'C:\ProgramData\ssh\sshd_config'){Copy-Item 'C:\ProgramData\ssh\sshd_config' $d};Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-TerminalServices-LocalSessionManager/Operational';StartTime=(Get-Date).AddDays(-7)} -ErrorAction SilentlyContinue|Select -First 200 TimeCreated,Id,LevelDisplayName,Message|Export-Csv (Join-Path $d rdp-events.csv) -NoTypeInformation;Write-Host "Remote access report: $d" -ForegroundColor Green}finally{Stop-Transcript|Out-Null}
